export const NODE_ATTRIBUTE='data-dsh-node';
export const MODEL_ID='dsh-document-model';
export const RUNTIME_ID='dsh-document-runtime';
const STYLE_ID='dsh-document-styles';
const HTML_NS='http://www.w3.org/1999/xhtml';
const OMIT=new Set(['head','script','style','link','meta','title','base']);
const PROTECTED=new Set(['html','head','body']);
const STATES=new Set(['default','hover','disabled','loading']);
const INTERACTIONS=new Set(['navigate','back','modal','drawer','tabs','toggle','form','filter','feedback','state','scene']);
const ID={test:value=>typeof value==='string'&&/^[A-Za-z][A-Za-z0-9_.:-]{0,127}$/.test(value)&&!['__proto__','constructor','prototype'].includes(value)};
const clone=value=>JSON.parse(JSON.stringify(value));
const object=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);
const own=(value,key)=>Object.prototype.hasOwnProperty.call(value,key);
const uid=prefix=>`${prefix}-${randomUUID()}`;
export class DocumentModelError extends Error {constructor(code,message,details={}){super(message);this.name='DocumentModelError';this.code=code;this.details=details;}}
