const children=node=>node.tagName==='template'?(node.content?.childNodes||[]):(node.childNodes||[]);
function walk(root,fn){fn(root);if(root.content){root.content.parentNode=root;walk(root.content,fn)}for(const child of root.childNodes||[])walk(child,fn);}
