const controlled=node=>['model','runtime','styles'].includes(attr(node,'data-dsh-controlled'));
const editable=node=>!!node.tagName&&!OMIT.has(node.tagName)&&!controlled(node);
const parentElement=node=>{let current=node.parentNode;while(current&&!current.tagName)current=current.parentNode;return current};
const textValue=node=>node.nodeName==='#text'?node.value:children(node).map(textValue).join('');
