function splitDeclarations(value){const output=[];let start=0,quote='',depth=0,comment=false;for(let i=0;i<value.length;i++){const char=value[i],next=value[i+1];if(comment){if(char==='*'&&next==='/'){comment=false;i++}continue}if(quote){if(char==='\\')i++;else if(char===quote)quote='';continue}if(char==='/'&&next==='*'){comment=true;i++;continue}if(char==='"'||char==="'"){quote=char;continue}if(char==='(')depth++;else if(char===')')depth--;else if(char===';'&&depth===0){output.push(value.slice(start,i));start=i+1}}output.push(value.slice(start));return output.filter(s=>s.trim()).map(raw=>{const clean=raw.replace(/\/\*[\s\S]*?\*\//g,'').trim(),index=clean.indexOf(':');const property=index>0?clean.slice(0,index).trim():null;return {raw,property:property?.startsWith('--')?property:(property?.toLowerCase()??null),value:index>0?clean.slice(index+1).trim():null}})}
