const styleMap=node=>Object.fromEntries(splitDeclarations(attr(node,'style')||'').filter(d=>d.property).map(d=>[d.property,d.value]));
function safeURL(value,{resource=false}={}){if(typeof value!=='string'||value.length>2_000_000||/[\x00-\x1f]/.test(value))return false;const compact=value.trim();if(/^(?:javascript|vbscript|file|dsh|vscode):/i.test(compact))return false;if(/^data:/i.test(compact))return resource&&/^data:(?:image\/(?:png|jpeg|webp|gif|svg\+xml|avif)|font\/|application\/(?:font|octet-stream))/i.test(compact);if(/^[A-Za-z][\w+.-]*:/.test(compact))return resource?/^https?:/i.test(compact):/^(?:https?|mailto|tel):/i.test(compact);return !compact.includes('\\')}
