function nodeRefs(interaction){const refs=new Set();for(const key of ['sourceId','targetId','successTargetId','errorTargetId','emptyTargetId'])if(interaction[key])refs.add(interaction[key]);for(const item of Array.isArray(interaction.items)?interaction.items:[])if(typeof item==='string')refs.add(item);else for(const key of ['triggerId','panelId'])if(item?.[key])refs.add(item[key]);for(const item of Array.isArray(interaction.rules)?interaction.rules:[])for(const key of ['nodeId','equalsNodeId'])if(item?.[key])refs.add(item[key]);return [...refs]}
