export function exportDocument(html,options={}){const {root,meta,diagnostics}=prepare(html,{});if(options.mode==='delivery'||options.mode===undefined)for(const node of elements(root).filter(n=>attr(n,'data-dsh-editor-overlay')!==undefined)){if(node.parentNode){detach(node);diagnose(diagnostics,'EDITOR_OVERLAY_REMOVED','Removed explicit editor overlay',attr(node,NODE_ATTRIBUTE),'warning')}}meta.runtime={...meta.runtime,mode:options.mode||'delivery',...(options.pageId?{pageId:options.pageId}:{}),...(options.pageURLs?{pageURLs:options.pageURLs}:{})};const model=finish(root,meta,diagnostics,options);return {html:model.html,diagnostics:model.diagnostics};}

export function documentOperationsHelp(type){
  const constraints=['One batch is atomic. expectedHash/expectedHashes can guard referenced subtree versions.','Selection scope grants only admitted roots and descendants; structural edits cannot inject global styles/scripts.','Locked objects need an explicit trusted user layer unlock.','Shared edits require scope:instance|definition; definition propagation still checks every affected node.'];
  const operations={
    text:{fields:{nodeIds:'nonempty stable ID array',value:'string <=200000 characters',mode:'leaf (default) refuses nested elements; direct retains nested elements',scope:'instance|definition for shared nodes'},example:{type:'text',nodeIds:['n-title'],value:'Updated heading'}},
    style:{fields:{nodeIds:'selected IDs',styles:'CSS property -> string|finite number|null; null removes declaration; dimensional numbers become px',breakpoint:'optional mobile|tablet|desktop|{minWidth?,maxWidth?}',scope:'instance|definition'},example:{type:'style',nodeIds:['n-card'],styles:{display:'grid',gridTemplateColumns:'1fr',gap:16},breakpoint:'mobile',scope:'instance'}},
    attributes:{fields:{nodeIds:'selected IDs',attributes:'attribute -> string|boolean|null; reserved data-dsh-*, style and on* fields forbidden',scope:'instance|definition'},example:{type:'attributes',nodeIds:['n-image'],attributes:{src:'../assets/photo.png',alt:'Product photo'}}},
    visibility:{fields:{nodeIds:'selected IDs',hidden:'boolean',scope:'instance|definition'}},lock:{fields:{nodeIds:'selected IDs',locked:'boolean; false requires user allowUnlock:true'}},
    insert:{fields:{parentId:'admitted container ID',html:'real HTML fragment <=2 MB',index:'optional element-child index',scope:'instance for shared containers'}},
    replace:{fields:{nodeIds:'exactly one non-document root',html:'one real root element; selected root ID retained',expectedHash:'optional exact subtree hash',scope:'instance for shared structure'}},
    remove:{fields:{nodeIds:'selected roots',scope:'instance for shared structure'},constraints:['Cannot erase locked descendants or leave shared definitions in use. Outside interaction invalidation needs broader scope.']},
    duplicate:{fields:{nodeIds:'selected roots',scope:'instance for shared structure'},constraints:['Fresh stable IDs and internal references. DOM id aliases are renamed with a diagnostic for external ID-specific CSS.']},
    move:{fields:{nodeIds:'selection roots, no ancestor+descendant pairs',parentId:'admitted container (or same parent for reorder)',index:'element index after removing moved roots',scope:'instance for shared structure'}},
    align:{fields:{nodeIds:'selected IDs',axis:'horizontal|vertical',value:'start|center|end|stretch',layout:'optional measured parent {display,direction}',scope:'instance|definition'}},
    distribute:{fields:{nodeIds:'all siblings of one authorized parent',axis:'horizontal|vertical',gap:'optional CSS gap; omitted uses space-between',scope:'instance|definition'}},
    'interaction.set':{fields:{interaction:'interaction object; source and every controlled target must be authorized'},schema:{common:{id:'optional valid unique ID',type:'navigate|back|modal|drawer|tabs|toggle|form|filter|feedback|state|scene',sourceId:'stable event source ID',event:'click default; form defaults submit; filter defaults input; also change/pointerenter/pointerleave'},back:{behavior:'Preview requests read-only Canvas view-history back; delivery calls browser history.back()'},navigate:{targetId:'optional same-page target',pageId:'optional page ID',url:'optional safe URL; provide at least one target'},modal:{targetId:'required',action:'open|close|toggle',display:'optional reveal display, e.g. flex'},drawer:{targetId:'required',action:'open|close|toggle',display:'optional reveal display'},tabs:{items:'[{triggerId,panelId}] with distinct pairs; triggers inside source',activeId:'optional item triggerId'},toggle:{targetId:'required',property:'hidden(default)|class|aria-pressed',className:'one class token when property=class'},form:{rules:'[{nodeId,required?,minLength?,maxLength?,pattern?,type?:email,equalsNodeId?}]',successTargetId:'optional leaf',errorTargetId:'optional leaf',successMessage:'optional string',errorMessage:'optional string'},filter:{items:'stable node ID array',emptyTargetId:'optional empty message ID',caseSensitive:'optional boolean'},feedback:{targetId:'leaf ID',text:'string',kind:'info|success|error'},state:{targetId:'optional, defaults sourceId',state:'default|hover|disabled|loading'},scene:{sceneId:'declared scene ID'}},examples:[{type:'interaction.set',interaction:{id:'i-open',type:'modal',sourceId:'n-open',targetId:'n-dialog',action:'open'}},{type:'interaction.set',interaction:{id:'i-next',type:'navigate',sourceId:'n-next',pageId:'page-details'}},{type:'interaction.set',interaction:{id:'i-validate',type:'form',sourceId:'n-form',rules:[{nodeId:'n-email',required:true,type:'email'}],successTargetId:'n-success',errorTargetId:'n-error'}}]},
    'interaction.remove':{fields:{id:'existing interaction ID'}},
    'state.set':{fields:{nodeIds:'selected IDs',states:'{default?,hover?,disabled?,loading?} of variant objects',active:'optional default|hover|disabled|loading',scope:'instance|definition'},variant:{styles:'optional CSS map',attributes:'optional safe attribute map',text:'optional leaf text',hidden:'optional boolean'}},
    'state.reset':{fields:{nodeIds:'selected IDs',scope:'instance|definition'}},
    'scene.set':{fields:{scene:'{id?,name?,kind?:empty|loading|error|success|custom,nodes:{[nodeId]:variant}}',activate:'optional boolean'},variant:{styles:'CSS map',attributes:'safe attribute map',text:'leaf text',hidden:'boolean'},example:{type:'scene.set',scene:{id:'scene-empty',name:'Empty results',kind:'empty',nodes:{'n-results':{hidden:true},'n-empty':{hidden:false}}},activate:true}},
    'scene.reset':{fields:{id:'optional scene ID; omitted deactivates all scenes',remove:'optional true deletes the named definition, requires id'}},
    'definition.set':{fields:{definition:'{id,name?,rootId,instanceIds:[stable IDs]} all roots authorized'},constraints:['Corresponding descendants use unique data-dsh-slot values. Scope is explicit; no similarity matching.']},
    'definition.remove':{fields:{id:'existing definition ID; all roots must be authorized'},constraints:['Detaches relationships and retains actual instance HTML.']},
    'override.reset':{fields:{nodeIds:'instance IDs/slot descendants',keys:'optional existing override fields, e.g. text, state, style.color, responsive.mobile.width'}},
  };
  if(!type)return {purpose:'Discover exact AST operations before editing real saved HTML.',constraints,operations:Object.keys(operations),discover:'Call edit.operations with type to load only that operation and examples.',examples:[operations.text.example,operations.style.example]};
  if(!own(operations,type))return {error:'UNKNOWN_OPERATION',type,operations:Object.keys(operations)};
  return {type,constraints,...clone(operations[type])};
}

export function interactionRuntimeSource(){return '('+designRuntime.toString()+')();'}
