      if(item.type==='navigate'){if(item.targetId){find(item.targetId)?.scrollIntoView({block:'start',behavior:'smooth'});return}if(item.pageId){if(meta.runtime?.mode==='preview'&&window.parent!==window){window.parent.postMessage({type:'dsh:runtime',action:'navigate',pageId:item.pageId},'*');return}location.href=meta.runtime?.pageURLs?.[item.pageId]||'pages/'+encodeURIComponent(item.pageId)+'.html';return}if(item.url)location.href=item.url;}
      else if(item.type==='modal'||item.type==='drawer')modal(item);
