    for(const [id,config] of Object.entries(meta.states)){state.states[id]=config.active||'default';setState(id,state.states[id]);const node=find(id);node?.addEventListener('pointerenter',()=>{if(state.states[id]==='default'&&config.variants.hover)setState(id,'hover')});node?.addEventListener('pointerleave',()=>{if(state.states[id]==='hover')setState(id,'default')})}
    if(state.scene)setScene(state.scene);
    function reset(){for(const id of baselines.keys())restore(id);opened=[];state.scene=null;state.feedback={};state.forms={};state.tabs={};state.states={};for(const [id,config] of Object.entries(meta.states))setState(id,config.active||'default');for(const item of meta.interactions)if(item.type==='tabs')tabs(item,item.activeId||item.items?.[0]?.triggerId);if(meta.scenes.active)setScene(meta.scenes.active);state.dirty=false;}
    function getState(){const snapshot=JSON.parse(JSON.stringify(state)),controls={visibility:{},displays:{},classes:{},pressed:{},texts:{},open:{}};for(const item of meta.interactions){const refs=[item.targetId,item.successTargetId,item.errorTargetId,item.emptyTargetId,...(item.type==='filter'?item.items||[]:[]),...(item.type==='tabs'?(item.items||[]).map(entry=>entry.panelId):[])].filter(Boolean);for(const id of refs){const node=find(id);if(!node)continue;controls.visibility[id]=node.hidden||getComputedStyle(node).display==='none'||getComputedStyle(node).visibility==='hidden';controls.displays[id]=getComputedStyle(node).display}if(item.type==='tabs'){const entry=(item.items||[]).find(entry=>find(entry.triggerId)?.getAttribute('aria-selected')==='true');if(entry)snapshot.tabs[item.id]=entry.triggerId}if(item.type==='toggle'&&item.property==='class'){const node=find(item.targetId);if(node){controls.classes[item.targetId] ||= {};controls.classes[item.targetId][item.className]=node.classList.contains(item.className)}}if(item.type==='toggle'&&item.property==='aria-pressed'){const node=find(item.targetId);if(node)controls.pressed[item.targetId]=node.getAttribute('aria-pressed')==='true'}if(['modal','drawer'].includes(item.type)){const node=find(item.targetId);if(node?.tagName==='DIALOG')controls.open[item.targetId]=!!node.open}for(const id of item.type==='feedback'?[item.targetId]:item.type==='form'?[item.successTargetId,item.errorTargetId]:[]){const node=find(id);if(node&&!node.children.length)controls.texts[id]=node.textContent}}snapshot.controls=controls;return snapshot;}
    document.addEventListener('input',()=>{state.dirty=true});document.addEventListener('change',()=>{state.dirty=true});
    window.__DSH_DESIGN_RUNTIME__={setScene,resetScene,setState:(id,value)=>{const applied=setState(id,value);if(applied)state.dirty=true;return applied},reset,getState};
    document.addEventListener('dsh:scene',event=>event.detail?.reset?resetScene():setScene(event.detail?.id));document.addEventListener('dsh:preview-reset',reset);
    document.addEventListener('keydown',event=>{if(event.key==='Escape'&&opened.length){const last=opened.pop();if(last.node.open)last.node.close?.();hide(last.node,true);last.previous?.focus?.();event.preventDefault()}});
